import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import toast from 'react-hot-toast';
import Layout from '../../components/Layout';
import StatusBadge from '../../components/StatusBadge';
import API from '../../api/axios';

const STATUSES = ['pending', 'confirmed', 'processing', 'completed', 'cancelled'];

export default function OwnerOrderDetail() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [order, setOrder] = useState(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [invoicing, setInvoicing] = useState(false);
  const [statusForm, setStatusForm] = useState({ status: '', ownerNote: '' });
  const [invoiceForm, setInvoiceForm] = useState({ tax: 0, discount: 0, ownerNote: '' });
  const [invoiceResult, setInvoiceResult] = useState(null);

  const fetchOrder = () => {
    API.get(`/owner/orders/${id}`)
      .then(({ data }) => {
        setOrder(data.order);
        setStatusForm({ status: data.order.status, ownerNote: data.order.ownerNote || '' });
        setInvoiceForm({ tax: data.order.tax || 0, discount: data.order.discount || 0, ownerNote: data.order.ownerNote || '' });
      })
      .finally(() => setLoading(false));
  };

  useEffect(() => { fetchOrder(); }, [id]); // eslint-disable-line

  const handleStatusUpdate = async (e) => {
    e.preventDefault();
    setSaving(true);
    try {
      await API.put(`/owner/orders/${id}/status`, statusForm);
      toast.success('Order status updated');
      fetchOrder();
    } catch {
      toast.error('Failed to update status');
    } finally {
      setSaving(false);
    }
  };

  const handleCreateInvoice = async (e) => {
    e.preventDefault();
    if (!window.confirm('Create invoice and send to customer via WhatsApp?')) return;
    setInvoicing(true);
    try {
      const { data } = await API.post(`/owner/orders/${id}/invoice`, invoiceForm);
      toast.success(data.message);
      setInvoiceResult(data);
      fetchOrder();
    } catch (err) {
      toast.error(err.response?.data?.message || 'Failed to create invoice');
    } finally {
      setInvoicing(false);
    }
  };

  const handleDownloadInvoice = () => {
    window.open(`/api/owner/orders/${id}/invoice/download`, '_blank');
  };

  if (loading) return <Layout title="Order Detail"><div className="spinner" /></Layout>;
  if (!order) return <Layout title="Order Detail"><div className="alert alert-error">Order not found</div></Layout>;

  const canInvoice = ['pending', 'confirmed', 'processing'].includes(order.status);

  return (
    <Layout title={`Order ${order.orderNumber}`}>
      <div style={{ display: 'flex', alignItems: 'center', gap: '1rem', marginBottom: '1.5rem', flexWrap: 'wrap' }}>
        <button className="btn btn-ghost btn-sm" onClick={() => navigate('/owner/orders')}>← Back</button>
        <h1 className="page-title" style={{ margin: 0 }}>{order.orderNumber}</h1>
        <StatusBadge status={order.status} />
      </div>

      <div className="grid-2" style={{ alignItems: 'start' }}>
        {/* Left column */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>

          {/* Customer Info */}
          <div className="card">
            <h3 style={{ fontWeight: 700, marginBottom: '1rem', fontSize: '0.95rem' }}>Customer Info</h3>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem', fontSize: '0.875rem' }}>
              <div style={{ display: 'flex', gap: '0.5rem' }}>
                <span style={{ color: '#6b7280', minWidth: 90 }}>Name:</span>
                <strong>{order.customerName}</strong>
              </div>
              <div style={{ display: 'flex', gap: '0.5rem' }}>
                <span style={{ color: '#6b7280', minWidth: 90 }}>Phone:</span>
                <span>{order.customerPhone}</span>
              </div>
              <div style={{ display: 'flex', gap: '0.5rem' }}>
                <span style={{ color: '#6b7280', minWidth: 90 }}>Email:</span>
                <span>{order.customerEmail || '—'}</span>
              </div>
              <div style={{ display: 'flex', gap: '0.5rem' }}>
                <span style={{ color: '#6b7280', minWidth: 90 }}>WhatsApp:</span>
                <span>{order.customerWhatsapp || '—'}</span>
              </div>
              {order.deliveryAddress && (
                <div style={{ display: 'flex', gap: '0.5rem' }}>
                  <span style={{ color: '#6b7280', minWidth: 90 }}>Address:</span>
                  <span>{order.deliveryAddress}</span>
                </div>
              )}
              {order.customerNote && (
                <div style={{ marginTop: '0.5rem', padding: '0.6rem', background: '#fef9c3', borderRadius: '0.4rem', fontSize: '0.8rem', color: '#854d0e' }}>
                  📝 {order.customerNote}
                </div>
              )}
            </div>
          </div>

          {/* Items Table */}
          <div className="card" style={{ padding: 0, overflow: 'hidden' }}>
            <div style={{ padding: '1rem 1.25rem', borderBottom: '1px solid #f3f4f6' }}>
              <h3 style={{ fontWeight: 700, fontSize: '0.95rem' }}>Order Items</h3>
            </div>
            <table>
              <thead>
                <tr>
                  <th>Item</th>
                  <th>Qty</th>
                  <th>Unit Price</th>
                  <th>Subtotal</th>
                </tr>
              </thead>
              <tbody>
                {order.items.map((item, i) => (
                  <tr key={i}>
                    <td>
                      <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                        {item.image ? (
                          <img src={`/uploads/${item.image}`} alt="" style={{ width: 32, height: 32, borderRadius: '0.35rem', objectFit: 'cover' }} />
                        ) : (
                          <div style={{ width: 32, height: 32, borderRadius: '0.35rem', background: '#f3f4f6', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#9ca3af', fontSize: '0.8rem' }}>📦</div>
                        )}
                        <strong>{item.name}</strong>
                      </div>
                    </td>
                    <td>{item.quantity} {item.unit}</td>
                    <td>{item.price?.toFixed(2)}</td>
                    <td><strong>{item.subtotal?.toFixed(2)}</strong></td>
                  </tr>
                ))}
              </tbody>
            </table>
            <div style={{ padding: '1rem 1.25rem', borderTop: '1px solid #f3f4f6' }}>
              <div style={{ display: 'flex', justifyContent: 'flex-end', flexDirection: 'column', alignItems: 'flex-end', gap: '0.25rem', fontSize: '0.875rem' }}>
                <div>Subtotal: <strong>{order.subtotal?.toFixed(2)}</strong></div>
                {order.tax > 0 && <div>Tax: <strong>{order.tax?.toFixed(2)}</strong></div>}
                {order.discount > 0 && <div>Discount: <strong>-{order.discount?.toFixed(2)}</strong></div>}
                <div style={{ fontSize: '1rem', marginTop: '0.25rem' }}>
                  Total: <strong style={{ color: '#2563eb' }}>{order.total?.toFixed(2)}</strong>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Right column */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>

          {/* Update Status */}
          <div className="card">
            <h3 style={{ fontWeight: 700, marginBottom: '1rem', fontSize: '0.95rem' }}>Update Status</h3>
            <form onSubmit={handleStatusUpdate}>
              <div className="form-group">
                <label className="form-label">Order Status</label>
                <select className="form-select" value={statusForm.status} onChange={(e) => setStatusForm({ ...statusForm, status: e.target.value })}>
                  {STATUSES.map((s) => (
                    <option key={s} value={s}>{s.charAt(0).toUpperCase() + s.slice(1)}</option>
                  ))}
                </select>
              </div>
              <div className="form-group">
                <label className="form-label">Internal Note (optional)</label>
                <textarea className="form-textarea" style={{ minHeight: 60 }} value={statusForm.ownerNote} onChange={(e) => setStatusForm({ ...statusForm, ownerNote: e.target.value })} placeholder="Note for your records…" />
              </div>
              <button type="submit" className="btn btn-primary" style={{ width: '100%' }} disabled={saving}>
                {saving ? 'Updating…' : 'Update Status'}
              </button>
            </form>
          </div>

          {/* Create Invoice */}
          <div className="card">
            <h3 style={{ fontWeight: 700, marginBottom: '0.5rem', fontSize: '0.95rem' }}>Create & Send Invoice</h3>
            <p style={{ fontSize: '0.8rem', color: '#6b7280', marginBottom: '1rem' }}>
              Generate a PDF invoice and automatically send it to the customer's WhatsApp.
            </p>

            {invoiceResult && (
              <div className="alert alert-success" style={{ marginBottom: '1rem' }}>
                ✅ {invoiceResult.message}
                {invoiceResult.invoicePdfUrl && (
                  <div style={{ marginTop: '0.4rem' }}>
                    <a href={invoiceResult.invoicePdfUrl} target="_blank" rel="noreferrer" style={{ color: '#166534', fontWeight: 600, fontSize: '0.8rem' }}>
                      📄 View Invoice PDF
                    </a>
                  </div>
                )}
              </div>
            )}

            {canInvoice ? (
              <form onSubmit={handleCreateInvoice}>
                <div className="grid-2">
                  <div className="form-group">
                    <label className="form-label">Tax Amount</label>
                    <input className="form-input" type="number" min="0" step="0.01" value={invoiceForm.tax} onChange={(e) => setInvoiceForm({ ...invoiceForm, tax: e.target.value })} />
                  </div>
                  <div className="form-group">
                    <label className="form-label">Discount Amount</label>
                    <input className="form-input" type="number" min="0" step="0.01" value={invoiceForm.discount} onChange={(e) => setInvoiceForm({ ...invoiceForm, discount: e.target.value })} />
                  </div>
                </div>
                <div className="form-group">
                  <label className="form-label">Message to Customer (optional)</label>
                  <textarea className="form-textarea" style={{ minHeight: 60 }} value={invoiceForm.ownerNote} onChange={(e) => setInvoiceForm({ ...invoiceForm, ownerNote: e.target.value })} placeholder="Thank you for your order!" />
                </div>
                <div style={{ background: '#f0fdf4', borderRadius: '0.5rem', padding: '0.75rem', marginBottom: '1rem', fontSize: '0.8rem', color: '#166534' }}>
                  <strong>Total Preview:</strong>{' '}
                  {(order.subtotal + parseFloat(invoiceForm.tax || 0) - parseFloat(invoiceForm.discount || 0)).toFixed(2)}
                </div>
                <button type="submit" className="btn btn-success" style={{ width: '100%' }} disabled={invoicing}>
                  {invoicing ? 'Generating & Sending…' : '📤 Create Invoice & Send via WhatsApp'}
                </button>
              </form>
            ) : (
              <div>
                {order.invoicePdfPath && (
                  <button className="btn btn-outline" style={{ width: '100%' }} onClick={handleDownloadInvoice}>
                    📄 Download Invoice PDF
                  </button>
                )}
                <div style={{ marginTop: '0.75rem', padding: '0.75rem', background: '#f3f4f6', borderRadius: '0.5rem', fontSize: '0.8rem', color: '#6b7280' }}>
                  Invoice already sent. Status: <StatusBadge status={order.status} />
                </div>
              </div>
            )}
          </div>

          {/* Notification Status */}
          <div className="card">
            <h3 style={{ fontWeight: 700, marginBottom: '0.75rem', fontSize: '0.95rem' }}>Notification Status</h3>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem', fontSize: '0.8rem' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <span>Quotation sent to customer</span>
                <span className={`badge ${order.quotationSentToCustomer ? 'badge-green' : 'badge-gray'}`}>
                  {order.quotationSentToCustomer ? '✓ Sent' : 'Not sent'}
                </span>
              </div>
              <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <span>Invoice sent to customer</span>
                <span className={`badge ${order.invoiceSentToCustomer ? 'badge-green' : 'badge-gray'}`}>
                  {order.invoiceSentToCustomer ? '✓ Sent' : 'Not sent'}
                </span>
              </div>
              <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <span>Order notified to store</span>
                <span className={`badge ${order.notificationSentToOwner ? 'badge-green' : 'badge-gray'}`}>
                  {order.notificationSentToOwner ? '✓ Sent' : 'Not sent'}
                </span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </Layout>
  );
}
